use std::fs;
use std::io::{Read, Write};
use std::net::TcpStream;
use std::path::{Path, PathBuf};
use std::time::Duration;

use crate::package::{verify_package_artifact, PackageManifest, PackageOrigin};

/// Manages atomic A/B hot-update slots for modules without requiring APK reinstallation.
pub struct HotUpdateManager {
    storage_root: PathBuf,
        trusted_pubkey_hex: String,
        }

        impl HotUpdateManager {
            /// Creates a new hot-update manager rooted at the app's private internal storage.
                pub fn new<P: AsRef<Path>>(storage_root: P, trusted_pubkey_hex: String) -> Self {
                        Self {
                                    storage_root: storage_root.as_ref().to_path_buf(),
                                                trusted_pubkey_hex,
                                                        }
                                                            }

                                                                /// Fetches an artifact via P2P chunks, direct HTTP/HTTPS URL, or hybrid fallback,
                                                                    /// verifies its cryptographic signature, and atomically activates the updated slot.
                                                                        pub fn install_or_hot_update(&self, manifest: &PackageManifest) -> Result<PathBuf, String> {
                                                                                let raw_bytes = match &manifest.origin {
                                                                                            PackageOrigin::HttpUrl { url } => self.fetch_via_http(url)?,
                                                                                                        PackageOrigin::P2pSwarm {
                                                                                                                        info_hash,
                                                                                                                                        bootstrap_peers,
                                                                                                                                                        chunk_size_bytes,
                                                                                                                                                                    } => self.fetch_via_p2p(info_hash, bootstrap_peers, *chunk_size_bytes)?,
                                                                                                                                                                                PackageOrigin::Hybrid {
                                                                                                                                                                                                info_hash,
                                                                                                                                                                                                                bootstrap_peers,
                                                                                                                                                                                                                                fallback_url,
                                                                                                                                                                                                                                            } => self
                                                                                                                                                                                                                                                            .fetch_via_p2p(info_hash, bootstrap_peers, 65536)
                                                                                                                                                                                                                                                                            .or_else(|_| self.fetch_via_http(fallback_url))?,
                                                                                                                                                                                                                                                                                    };

                                                                                                                                                                                                                                                                                            // Cryptographic validation before touching any active slot
                                                                                                                                                                                                                                                                                                    verify_package_artifact(&raw_bytes, manifest, &self.trusted_pubkey_hex)?;

                                                                                                                                                                                                                                                                                                            let module_dir = self.storage_root.join("modules").join(&manifest.id);
                                                                                                                                                                                                                                                                                                                    fs::create_dir_all(&module_dir).map_err(|e| e.to_string())?;

                                                                                                                                                                                                                                                                                                                            // Determine inactive A/B slot to guarantee rollback safety
                                                                                                                                                                                                                                                                                                                                    let active_marker = module_dir.join("ACTIVE_SLOT");
                                                                                                                                                                                                                                                                                                                                            let current_slot = fs::read_to_string(&active_marker).unwrap_or_else(|_| "slot_b".into());
                                                                                                                                                                                                                                                                                                                                                    let next_slot = if current_slot.trim() == "slot_a" {
                                                                                                                                                                                                                                                                                                                                                                "slot_b"
                                                                                                                                                                                                                                                                                                                                                                        } else {
                                                                                                                                                                                                                                                                                                                                                                                    "slot_a"
                                                                                                                                                                                                                                                                                                                                                                                            };

                                                                                                                                                                                                                                                                                                                                                                                                    let target_file = module_dir.join(format!("{}.bin", next_slot));
                                                                                                                                                                                                                                                                                                                                                                                                            let manifest_file = module_dir.join(format!("{}.manifest.json", next_slot));

                                                                                                                                                                                                                                                                                                                                                                                                                    fs::write(&target_file, &raw_bytes).map_err(|e| e.to_string())?;
                                                                                                                                                                                                                                                                                                                                                                                                                            let serialized_manifest = serde_json::to_string_pretty(manifest).map_err(|e| e.to_string())?;
                                                                                                                                                                                                                                                                                                                                                                                                                                    fs::write(&manifest_file, serialized_manifest).map_err(|e| e.to_string())?;

                                                                                                                                                                                                                                                                                                                                                                                                                                            // Atomic pointer swap
                                                                                                                                                                                                                                                                                                                                                                                                                                                    fs::write(&active_marker, next_slot).map_err(|e| e.to_string())?;

                                                                                                                                                                                                                                                                                                                                                                                                                                                            Ok(target_file)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                    /// Reverts the active module slot to the previous known-good version.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        pub fn rollback_module(&self, module_id: &str) -> Result<String, String> {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                let module_dir = self.storage_root.join("modules").join(module_id);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        let active_marker = module_dir.join("ACTIVE_SLOT");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                let current_slot = fs::read_to_string(&active_marker).map_err(|e| e.to_string())?;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        let previous_slot = if current_slot.trim() == "slot_a" {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    "slot_b"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        "slot_a"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        let prev_artifact = module_dir.join(format!("{}.bin", previous_slot));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if !prev_artifact.exists() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return Err("No previous slot available for rollback".to_string());
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            fs::write(&active_marker, previous_slot).map_err(|e| e.to_string())?;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    Ok(previous_slot.to_string())
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            /// Lightweight P2P chunked transfer over TCP peer endpoints.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                /// Protocol frame: "GET_HASH:<info_hash>\n" -> returns raw verified payload bytes.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    fn fetch_via_p2p(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            &self,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    info_hash: &str,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            peers: &[String],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    _chunk_size: usize,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ) -> Result<Vec<u8>, String> {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                for peer in peers {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if let Ok(mut stream) = TcpStream::connect_timeout(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            &peer.parse().map_err(|_| "Invalid peer socket address".to_string())?,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            Duration::from_secs(5),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        let request = format!("GET_HASH:{}\n", info_hash);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if stream.write_all(request.as_bytes()).is_ok() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            let mut buffer = Vec::new();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if stream.read_to_end(&mut buffer).is_ok() && !buffer.is_empty() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return Ok(buffer);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        Err("Failed to retrieve package from P2P peers".to_string())
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                /// Invokes system curl/HTTPS client to fetch artifacts from standard repository URLs
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    /// without bloating Rust binary size with OpenSSL crates.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        fn fetch_via_http(&self, url: &str) -> Result<Vec<u8>, String> {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                let output = std::process::Command::new("curl")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            .args(["-fsSL", "--max-time", "30", url])
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        .output()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .map_err(|e| format!("Failed to invoke HTTP fetcher: {}", e))?;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if !output.status.success() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return Err(format!(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        "HTTP download failed with status: {}",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        String::from_utf8_lossy(&output.stderr)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    Ok(output.stdout)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }